1	//! Драйвер прогона: сигналы формы на сутках (`signals_for`), события суток из
2	//! частей с кэшем счётчика (`day_events`), правило размера круга по цене
3	//! касания (`OrderSizing`, R2), параметры суток одной структурой
4	//! (`DayParams`), очередь готовых результатов форм по порядку (`FormOrder`),
5	//! прогон всех форм над сутками потоками (`drive_day`) и окна сетапов
6	//! (`day_windows`). Вынесено из `bounce_grid` при разрезке B3 (ревью 23.09),
7	//! поведение не менялось.
8	
9	use std::collections::BTreeMap;
10	use std::path::PathBuf;
11	use std::sync::atomic::{AtomicUsize, Ordering};
12	use std::sync::Mutex;
13	use std::time::Instant;
14	
15	use hftbacktest::types::Event as HbtEvent;
16	
17	use crate::book::Side;
18	use crate::commands::lob::backtest::{
19	    approach_plan, bounce_plan, count_feed_events, deadline_ns_from_secs, early_exit_ns_from_secs,
20	    feed_compact_into, open_replay_feed, PlanShape, PoolLot,
21	};
22	use crate::lob::backtest::{
23	    drive_bounce, drive_bounce_windowed, drive_bounce_windowed_memo, with_backtest_over, BounceRun,
24	    BounceSignal, CompactEvent, DriveConfig, ExecLatency, QueueModelKind, RoundMemo, SignalWindows,
25	};
26	use crate::lob::levels::{H3Mode, TouchRecord};
27	use crate::lob::sigma::SigmaSeries;
28	
29	use super::args::{BounceGridArgs, DriverArg};
30	use super::carry::{cached_event_count, store_event_count};
31	use super::forms::GridForm;
32	use super::outputs::FormDayResult;
33	use super::sets::{Range, TouchContext, TouchFilter, CTX_AXES};
34	
35	/// Сигналы формы: план базы на каждое касание (`σ_H` за окно дедлайна — только
36	/// σ-формам); касания, для которых форму не построить, пропускаются и
37	/// считаются (второе значение). С `--signal approach` `touches` — это **вид**
38	/// записей подхода как касаний (`cached_approaches`/`touch_view_of_approach`:
39	/// `start_ms` = `arm_ms`), а план строится `approach_plan` от самой записи
40	/// подхода: вход ставится на взводе, а не на касании (F6, В-73).
41	#[allow(clippy::cast_precision_loss)]
42	fn signals_for(
43	    touches: &[TouchRecord],
44	    approaches: Option<&[crate::lob::levels::ApproachRecord]>,
45	    sigma: &SigmaSeries,
46	    form: &GridForm,
47	    p: &DayParams<'_>,
48	) -> anyhow::Result<(Vec<BounceSignal>, u64)> {
49	    let deadline_ns = deadline_ns_from_secs(form.deadline_secs)?;
50	    let early_exit_ns = early_exit_ns_from_secs(form.early_exit_secs)?;
51	    let mut skipped: u64 = 0;
52	    if let Some(ctx) = p.ctx {
53	        anyhow::ensure!(
54	            ctx.len() == touches.len(),
55	            "контекст касаний ({}) не совпадает с касаниями ({})",
56	            ctx.len(),
57	            touches.len()
58	        );
59	    }
60	    if let Some(ap) = approaches {
61	        anyhow::ensure!(
62	            ap.len() == touches.len(),
63	            "записи подхода ({}) не совпадают с их видом как касаний ({})",
64	            ap.len(),
65	            touches.len()
66	        );
67	    }
68	    let filter = TouchFilter::from_day(p);
69	    let mut signals: Vec<BounceSignal> = touches
70	        .iter()
71	        .enumerate()
72	        .filter_map(|(ti, t)| {
73	            if !filter.admits(ti, t) {
74	                skipped += 1;
75	                return None;
76	            }
77	            let sigma_bps = if form.form.needs_sigma() {
78	                sigma.sigma_bps(t.start_ms, form.deadline_secs)
79	            } else {
80	                None
81	            };
82	            let shape = PlanShape {
83	                lot: p.lot,
84	                post_only: p.post_only,
85	                trail_bps: 0.0,
86	                trail_activate_bps: 0.0,
87	                grid_legs: 1,
88	                grid_step_ticks: 0,
89	                // F6 (В-73): форма входа — ось сетки (`--entry-form`):
90	                // `single@fr` — прежняя нога, лестница — ноги от `from` до `to`
91	                // bps над стеной.
92	                entry_form: form.entry_form,
93	                deadline_ns,
94	                early_exit_ns,
95	                // F5 (В-74): режим срока жизни входа — из формы сетки
96	                // (`--entry-ttl-secs`), а условия «стена снята»/«цена ушла»
97	                // читают `--h3-usd` и `--band-exit-bps`.
98	                entry_ttl: form.entry_ttl,
99	                h3_usd: p.h3_usd,
100	                band_exit_bps: p.band_exit_bps,
101	                // F7 (Б-75): форма выхода — ось сетки (`--exit-form`).
102	                exit_form: form.exit_form,
103	            };
104	            let built = match approaches {
105	                Some(ap) => approach_plan(&ap[ti], p.tick, form.form, sigma_bps, shape),
106	                None => bounce_plan(t, p.tick, form.form, sigma_bps, shape),
107	            };
108	            let Some((dir, plan)) = built else {
109	                skipped += 1;
110	                return None;
111	            };
112	            Some(BounceSignal {
113	                t0_ns: t.start_ms.saturating_mul(1_000_000),
114	                sigma: dir,
115	                plan,
116	                profile: 0,
117	                qty: Some(p.order_qtys[ti]),
118	            })
119	        })
120	        .collect();
121	    signals.sort_by_key(|s| s.t0_ns);
122	    Ok((signals, skipped))
123	}
124	
125	/// События суток крейта из всех частей дня — в `Vec` **точного** размера:
126	/// сначала части считаются (`count_feed_events`), потом декодируются в
127	/// буфер с готовой ёмкостью. Рост удвоением держал старый и новый буфер
128	/// вместе (пик до 3× итога) и ронял сетку на сервере по OOM на сутках в
129	/// ~20 млн событий (2026-09-18); второй декод дешевле памяти.
130	pub(super) fn day_events(parts: &[PathBuf]) -> anyhow::Result<Vec<CompactEvent>> {
131	    let started = Instant::now();
132	    let mut total = 0usize;
133	    let mut counted_parts = 0usize;
134	    for path in parts {
135	        total += match cached_event_count(path) {
136	            Some(n) => n,
137	            None => {
138	                let mut feed = open_replay_feed(path)?;
139	                let n = count_feed_events(&mut feed);
140	                store_event_count(path, n);
141	                counted_parts += 1;
142	                n
143	            }
144	        };
145	    }
146	    let counted = started.elapsed().as_secs_f64();
147	    // Р6: сутки — компактными событиями (32 Б вместо 64); круги разворачивают свой кусок сами.
148	    let mut events: Vec<CompactEvent> = Vec::with_capacity(total);
149	    for path in parts {
150	        let mut feed = open_replay_feed(path)?;
151	        feed_compact_into(&mut feed, &mut events);
152	    }
153	    // Кэш числа событий — только ёмкость буфера: разошёлся — буфер просто
154	    // вырос, круги те же; сайдкары переписываются честным пересчётом.
155	    if events.len() != total {
156	        eprintln!(
157	            "bounce-grid:   события: кэш числа врал ({total} против {}), сайдкары пересчитаны",
158	            events.len()
159	        );
160	        for path in parts {
161	            let mut feed = open_replay_feed(path)?;
162	            let n = count_feed_events(&mut feed);
163	            store_event_count(path, n);
164	        }
165	    }
166	    eprintln!(
167	        "bounce-grid:   события: счёт {counted:.2}s ({counted_parts} из {} частей считано, остальные из кэша) · декод {:.2}s · {}",
168	        parts.len(),
169	        started.elapsed().as_secs_f64() - counted,
170	        events.len()
171	    );
172	    Ok(events)
173	}
174	
175	/// Правило размера круга (R2, ревью 23.09): лот считается по цене **каждого
176	/// касания**, а не одной ценой на символ. До исправления лот брался по цене
177	/// последнего касания всей записи: сигнал в начале месяца получал размер по
178	/// цене его конца — заглядывание вперёд, и номинал круга расходился с
179	/// `--order-usd` ровно на движение цены за запись (у монеты, выросшей вдвое,
180	/// ранние круги шли на половину заявленного номинала). Поля пула читаются
181	/// один раз на символ.
182	#[derive(Debug, Clone, Copy)]
183	pub(super) enum OrderSizing {
184	    /// `--order-qty-e9` — лот задан числом, от цены не зависит.
185	    Fixed(i64),
186	    /// `--order-qty-from-pool` — `order_size_22a` при цене касания.
187	    Pool22a(PoolLot),
188	    /// `--order-usd` — номинал при цене касания, не меньше 22а.
189	    Usd(PoolLot, f64),
190	}
191	
192	impl OrderSizing {
193	    pub(super) fn from_args(args: &BounceGridArgs, symbol: &str) -> anyhow::Result<Self> {
194	        if let Some(v) = args.order_qty_e9 {
195	            return Ok(Self::Fixed(v));
196	        }
197	        let lot = PoolLot::read(&args.root.join("instruments.csv"), symbol)?;
198	        Ok(match args.order_usd {
199	            Some(usd) => {
200	                anyhow::ensure!(
201	                    usd.is_finite() && usd > 0.0,
202	                    "{symbol}: --order-usd обязан быть положительным числом"
203	                );
204	                anyhow::ensure!(
205	                    lot.qty_step_e9 > 0,
206	                    "{symbol}: шаг лота в пуле обязан быть положительным"
207	                );
208	                Self::Usd(lot, usd)
209	            }
210	            None => Self::Pool22a(lot),
211	        })
212	    }
213	
214	    /// Лот в 1e-9 при цене `price_tick` (в тиках книги `tick_e9`). Цена —
215	    /// уровня (стены) в момент касания, а не будущей заявки входа: она
216	    /// известна в `t0` (заглядывания нет), а вход стоит в bps от неё — номинал
217	    /// круга отличается от `--order-usd` на эти bps, не на ход цены за запись.
218	    fn qty_e9(&self, price_tick: i64, tick_e9: i64) -> i64 {
219	        let price_e9 = price_tick.saturating_mul(tick_e9);
220	        match *self {
221	            Self::Fixed(v) => v,
222	            Self::Pool22a(lot) => lot.qty_22a_e9(price_e9),
223	            Self::Usd(lot, usd) => lot.qty_usd_e9(price_e9, usd),
224	        }
225	    }
226	
227	    /// Размер круга на каждое касание суток — по цене этого касания, с
228	    /// множителем `--order-qty-mult` (E7).
229	    pub(super) fn touch_qtys(&self, touches: &[TouchRecord], tick_e9: i64, mult: u32) -> Vec<f64> {
230	        touches
231	            .iter()
232	            .map(|t| {
233	                #[allow(clippy::cast_precision_loss)]
234	                let q = self
235	                    .qty_e9(t.price_tick, tick_e9)
236	                    .saturating_mul(i64::from(mult.max(1))) as f64
237	                    / 1e9;
238	                q
239	            })
240	            .collect()
241	    }
242	}
243	
244	/// Параметры прогона суток одной структурой (clippy держит предел семи аргументов).
245	#[derive(Debug, Clone, Copy)]
246	pub(super) struct DayParams<'a> {
247	    /// Память кругов по форме (G10, `--round-memo`); `None` — счёт с нуля.
248	    pub(super) memos: Option<&'a [Mutex<RoundMemo>]>,
249	    pub(super) tick: f64,
250	    pub(super) lot: f64,
251	    pub(super) rtt_ns: ExecLatency,
252	    /// Модель очереди/исполнения суток (`--queue-model`, F3) — одна на процесс.
253	    pub(super) queue_model: QueueModelKind,
254	    /// Размер круга на каждое касание суток (тот же порядок, что `touches`):
255	    /// лот по цене **этого** касания (R2, `OrderSizing`).
256	    pub(super) order_qtys: &'a [f64],
257	    pub(super) threads: usize,
258	    /// Вход пост-онли (В-72): у плана `post_only`, у сетки умолчание —
259	    /// включён (`BounceGridArgs::entry_post_only`).
260	    pub(super) post_only: bool,
261	    /// E3: входить только от фронтрана (`--frontrun-only`).
262	    pub(super) frontrun_only: bool,
263	    /// Порог уровня — проверяется и **в момент касания** (`H3Mode::holds_at_touch`).
264	    pub(super) mode: H3Mode,
265	    /// Номинал порога В-66 в долларах (`--h3-usd`): из него план считает
266	    /// `level_floor_qty` — порог «стена снята» (F5, В-74). `None` — условия
267	    /// F5 выключены (режим `touch`), иначе `run_bounce_grid` отказал бы.
268	    pub(super) h3_usd: Option<f64>,
269	    /// Полоса ухода цены, bps (F5, В-74, `--band-exit-bps`); `0` — условие
270	    /// выключено (режим `touch`).
271	    pub(super) band_exit_bps: f64,
272	    /// Фильтры базы в момент касания: возраст плотности и сила «×поток».
273	    pub(super) min_age_ms: Option<i64>,
274	    pub(super) min_flow_pct: Option<f64>,
275	    /// Ось стороны (`--side`): `None` — обе стороны.
276	    pub(super) side: Option<Side>,
277	    /// Доля съедания стены к касанию не больше этого процента (`eaten=`).
278	    pub(super) eaten_max_pct: Option<f64>,
279	    /// T4 (П-02, Г-86): доля съедания стены к касанию не меньше этого
280	    /// процента (`eaten_min=`) — зеркало `eaten_max_pct`.
281	    pub(super) eaten_min_pct: Option<f64>,
282	    /// Номинал стены при касании ≥ (`usd_min=`), доллары.
283	    pub(super) usd_min: Option<f64>,
284	    /// Контекст касаний суток (тот же порядок, что `touches`) — только когда
285	    /// у набора есть ключи контекста; границы — `ctx_ranges`.
286	    pub(super) ctx: Option<&'a [TouchContext]>,
287	    pub(super) ctx_ranges: [Range; CTX_AXES.len()],
288	    /// Ряд `σ` символа (все сутки записи подряд).
289	    pub(super) sigma: &'a SigmaSeries,
290	}
291	
292	/// Готовые результаты форм уходят в `sink` **по порядку форм**: форма,
293	/// закончившая раньше соседей с меньшим индексом, ждёт в буфере (не больше
294	/// числа потоков), чтобы дамп не зависел от числа потоков.
295	struct FormOrder<'a> {
296	    pending: BTreeMap<usize, (BounceRun, Vec<BounceSignal>, u64)>,
297	    next_form: usize,
298	    done: usize,
299	    sink: &'a mut (dyn FnMut(FormDayResult, &[BounceSignal]) -> anyhow::Result<()> + Send),
300	}
301	
302	/// Все формы над одними сутками: потоки берут формы по счётчику. `Setups`
303	/// — один проход книги на сутки (`SignalWindows`, общий для форм), дальше у
304	/// каждой формы движок только внутри кругов; `Full` — у каждой формы свой
305	/// `Backtest` над всеми событиями суток (эталон гейта).
306	///
307	/// Память (сервер, 2026-09-18): сигналы формы строятся **в потоке, когда
308	/// форма взята** (например, 48 форм × 100 тыс. касаний × 128 Б заранее — 600 МБ), а
309	/// результат формы отдаётся `sink` сразу и до конца суток не копится
310	/// (`FormOrder`). Возвращает число форм, отданных в `sink`.
311	///
312	/// `approaches` — записи подхода (F6, `--signal approach`): те же сутки и тот
313	/// же порядок, что `touches` (их вид как касания); `None` — сигнал по касаниям.
314	pub(super) fn drive_day(
315	    events: &[CompactEvent],
316	    windows: Option<&SignalWindows>,
317	    touches: &[TouchRecord],
318	    approaches: Option<&[crate::lob::levels::ApproachRecord]>,
319	    forms: &[GridForm],
320	    p: DayParams<'_>,
321	    sink: &mut (dyn FnMut(FormDayResult, &[BounceSignal]) -> anyhow::Result<()> + Send),
322	) -> anyhow::Result<usize> {
323	    // `--driver full` (эталон гейта) держит сутки 64-байтными событиями крейта — одна полная
324	    // развёртка на сутки, общая для форм; путь по окнам (`setups`) разворачивает только круги (Р6).
325	    let full: Vec<HbtEvent> = if windows.is_none() {
326	        events.iter().map(CompactEvent::expand).collect()
327	    } else {
328	        Vec::new()
329	    };
330	    let next = AtomicUsize::new(0);
331	    let failure: Mutex<Option<anyhow::Error>> = Mutex::new(None);
332	    let order = Mutex::new(FormOrder {
333	        pending: BTreeMap::new(),
334	        next_form: 0,
335	        done: 0,
336	        sink,
337	    });
338	    std::thread::scope(|scope| {
339	        for _ in 0..p.threads.max(1) {
340	            scope.spawn(|| loop {
341	                let i = next.fetch_add(1, Ordering::Relaxed);
342	                if i >= forms.len() {
343	                    break;
344	                }
345	                if failure.lock().map(|f| f.is_some()).unwrap_or(true) {
346	                    break;
347	                }
348	                let cfg = DriveConfig {
349	                    // R2: размер несёт каждый сигнал (`BounceSignal::qty`,
350	                    // `signals_for`); размер прогона сетке не нужен.
351	                    order_qty: 0.0,
352	                    first_order_id: 1,
353	                    queue_model: p.queue_model,
354	                };
355	                let step = signals_for(touches, approaches, p.sigma, &forms[i], &p).and_then(
356	                    |(signals, skipped)| {
357	                        let driven = match windows {
358	                            Some(w) => match p.memos {
359	                                // Память формы берёт один поток за раз: форма в наборе одна.
360	                                Some(ms) => {
361	                                    let mut m = ms[i]
362	                                        .lock()
363	                                        .unwrap_or_else(std::sync::PoisonError::into_inner);
364	                                    drive_bounce_windowed_memo(
365	                                        events, w, &signals, &cfg, p.rtt_ns, &mut m,
366	                                    )
367	                                }
368	                                None => drive_bounce_windowed(events, w, &signals, &cfg, p.rtt_ns),
369	                            },
370	                            None => with_backtest_over(
371	                                &full,
372	                                p.tick,
373	                                p.lot,
374	                                p.rtt_ns,
375	                                p.queue_model,
