295	/// Перевод `feed` → события крейта, с необязательным потолком времени.
296	/// `until_ns` сравнивается с `local_ts_ns` события (тем же полем, что несёт
297	/// каждое рыночное событие) — как только оно дошло до потолка, перевод
298	/// останавливается немедленно (`true`), не декодируя остаток файла: он не
299	/// нужен звонящему (`day_events`/`carry_events`) и стоил бы памяти. `None` —
300	/// прежнее поведение, весь `feed` до конца (`false`).
301	fn translate_feed_until(
302	    feed: &mut dyn Feed,
303	    until_ns: Option<i64>,
304	    sink: &mut impl FnMut(CompactEvent),
305	) -> bool {
306	    let mut known_bids: BTreeMap<i64, i64> = BTreeMap::new();
307	    let mut known_asks: BTreeMap<i64, i64> = BTreeMap::new();
308	
309	    while let Some(ev) = feed.next_event() {
310	        let FeedEvent::Market {
311	            local_ts_ns,
312	            payload,
313	            ..
314	        } = ev
315	        else {
316	            continue;
317	        };
318	        if let Some(until) = until_ns {
319	            if local_ts_ns >= until {
320	                return true;
321	            }
322	        }
323	        match payload {
324	            WsEvent::Book(up) => {
325	                // Р6: метка биржи — в мс, как пришла; `× 10⁶` делает `CompactEvent::expand`.
326	                let exch_ms = up.cts_ms;
327	                push_side(
328	                    sink,
329	                    &mut known_bids,
330	                    &up.bids,
331	                    up.is_snapshot,
332	                    exch_ms,
333	                    local_ts_ns,
334	                    true,
335	                );
336	                push_side(
337	                    sink,
338	                    &mut known_asks,
339	                    &up.asks,
340	                    up.is_snapshot,
341	                    exch_ms,
342	                    local_ts_ns,
343	                    false,
344	                );
345	            }
346	            WsEvent::Trade(t) => {
347	                let kind = if t.aggressor_is_buy {
348	                    EventKind::BuyTrade
349	                } else {
350	                    EventKind::SellTrade
351	                };
352	                sink(CompactEvent::new(
353	                    kind,
354	                    t.exch_ms,
355	                    local_ts_ns,
356	                    t.price_e9,
357	                    t.qty_e9,
358	                ));
359	            }
360	            WsEvent::Other | WsEvent::SubscribeFailed { .. } => {}
361	        }
362	    }
363	    false
364	}
365	
366	#[allow(clippy::too_many_arguments)]
367	fn push_side(
368	    sink: &mut impl FnMut(CompactEvent),
369	    known: &mut BTreeMap<i64, i64>,
370	    rows: &[(i64, i64)],
371	    is_snapshot: bool,
372	    exch_ms: i64,
373	    local_ts: i64,
374	    bid: bool,
375	) {
376	    let kind = if bid {
377	        EventKind::BidDepth
378	    } else {
379	        EventKind::AskDepth
380	    };
381	    let mut push = |px: i64, qty: i64| {
382	        sink(CompactEvent::new(kind, exch_ms, local_ts, px, qty));
383	    };
384	    if is_snapshot {
385	        let fresh: BTreeSet<i64> = rows.iter().map(|&(px, _)| px).collect();
386	        let stale: Vec<i64> = known
387	            .keys()
388	            .copied()
389	            .filter(|px| !fresh.contains(px))
390	            .collect();
391	        for px in stale {
392	            known.remove(&px);
393	            push(px, 0);
394	        }
395	    }
396	    for &(px, qty) in rows {
397	        if qty > 0 {
398	            known.insert(px, qty);
399	        } else {
400	            known.remove(&px);
401	        }
402	        push(px, qty);
403	    }
404	}

