26	/// `Feed` с одного суточного файла бинлога одного инструмента пула.
27	pub struct ReplayFeed<R: Read> {
28	    symbol: u16,
29	    tick_e9: i64,
30	    step_e9: i64,
31	    reader: binlog::Reader<R>,
32	    replayer: FileReplayer,
33	    pending: VecDeque<Event>,
34	    last_local_ts_ns: i64,
35	    done: bool,
36	}
