38	impl<R: Read> ReplayFeed<R> {
39	    /// `symbol` — тот же индекс пула, под которым файл писала `lob session`
40	    /// (см. doc модуля `feed`: тег события не имеет права быть `String`).
41	    pub fn open(symbol: u16, inner: R) -> Result<Self, BinlogError> {
42	        let reader = binlog::Reader::open(inner)?;
43	        let header = reader.header();
44	        Ok(Self {
45	            symbol,
46	            tick_e9: header.tick_e9,
47	            step_e9: header.step_e9,
48	            reader,
49	            replayer: FileReplayer::new(),
50	            pending: VecDeque::new(),
51	            last_local_ts_ns: 0,
52	            done: false,
53	        })
54	    }
55	
56	    /// Один и тот же вызов на одну запись — `FileReplayer::push_frame`
57	    /// сам решает, закрывает ли эта запись группу (снапшот сменился на
58	    /// дельту, дельта на сделку, дельта на снапшот) или продолжает её,
59	    /// ровно так же, как `commands::lob::replay_symbol` уже это делает.
60	    fn push_record(&mut self, rec: &Record) {
61	        self.last_local_ts_ns = rec.local_ts_ns;
62	        let mut ups = Vec::new();
63	        let mut trade_points = Vec::new();
64	        self.replayer.push_frame(
65	            std::slice::from_ref(rec),
66	            self.tick_e9,
67	            self.step_e9,
68	            &mut ups,
69	            &mut trade_points,
70	        );
71	        for up in ups {
72	            self.pending.push_back(Event::Market {
73	                symbol: self.symbol,
74	                local_ts_ns: rec.local_ts_ns,
75	                parse_latency_ns: None,
76	                payload: WsEvent::Book(up),
77	            });
78	        }
79	        if is_trade_ev(rec.ev) {
80	            self.pending.push_back(Event::Market {
81	                symbol: self.symbol,
82	                local_ts_ns: rec.local_ts_ns,
83	                parse_latency_ns: None,
84	                payload: WsEvent::Trade(Trade {
85	                    exch_ms: rec.exch_ts_ns / 1_000_000,
86	                    price_e9: rec.price_ticks * self.tick_e9,
87	                    qty_e9: rec.qty_lots * self.step_e9,
88	                    aggressor_is_buy: rec.ev == LOCAL_BUY_TRADE_EVENT,
89	                    block: rec.block,
90	                    rpi: rec.rpi,
91	                }),
92	            });
93	        }
94	    }
95	}
