97	impl<R: Read> Feed for ReplayFeed<R> {
98	    fn next_event(&mut self) -> Option<Event> {
99	        loop {
100	            if let Some(ev) = self.pending.pop_front() {
101	                return Some(ev);
102	            }
103	            if self.done {
104	                return None;
105	            }
106	            match self.reader.read_frame() {
107	                Ok(Some(records)) => {
108	                    for rec in &records {
