533	/// Читает varint из `buf`, начиная с `*pos`, и продвигает `*pos`. Ошибка —
534	/// не паника: `buf.get` вместо индексации, явный предел на число байт,
535	/// потому что оборванный кадр обязан дать `Corrupt`, а не читать за границей.
536	fn read_uvarint(buf: &[u8], pos: &mut usize) -> Result<u64, BinlogError> {
537	    let mut result: u64 = 0;
538	    let mut shift = 0u32;
539	    loop {
540	        let byte = *buf
541	            .get(*pos)
542	            .ok_or_else(|| BinlogError::Corrupt("varint обрезан".to_string()))?;
543	        *pos += 1;
544	        if shift >= 64 {
545	            return Err(BinlogError::Corrupt("varint длиннее 64 бит".to_string()));
546	        }
547	        result |= ((byte & 0x7f) as u64) << shift;
548	        if byte & 0x80 == 0 {
549	            return Ok(result);
550	        }
551	        shift += 7;
552	    }
553	}
