843	/// Разбирает уже разжатое тело кадра v3: эпоха, затем группы сообщений до
844	/// конца среза. Число записей группы проверяется против остатка кадра **до**
845	/// чтения: каждая запись — минимум два байта, поэтому группа, объявившая
846	/// записей больше, чем в кадре осталось байт, — порча, а не повод крутить
847	/// цикл по счётчику, который пришёл с диска.
848	pub fn decode_frame_payload_v3(payload: &[u8]) -> Result<Vec<Record>, BinlogError> {
849	    let epoch_ns = read_frame_epoch(payload)?;
850	    let mut st = DeltaState::new();
851	    let mut pos = FRAME_EPOCH_LEN;
852	    let mut out = Vec::new();
853	    while pos < payload.len() {
854	        let ev = read_uvarint(payload, &mut pos)?;
855	        let exch_delta = read_zigzag(payload, &mut pos)?;
856	        let local_delta = read_zigzag(payload, &mut pos)?;
857	        let attrs = read_uvarint(payload, &mut pos)?;
858	        if attrs & !ATTRS_KNOWN != 0 {
859	            return Err(BinlogError::Corrupt(format!(
860	                "неизвестный бит attrs группы: {attrs:#x}"
861	            )));
862	        }
863	        let count = read_uvarint(payload, &mut pos)?;
864	        let remaining = (payload.len() - pos) as u64;
865	        if count > remaining {
866	            return Err(BinlogError::Corrupt(format!(
867	                "группа объявила {count} записей, а в кадре осталось {remaining} байт"
868	            )));
869	        }
870	        let exch_ts_ns = epoch_ns.wrapping_add(exch_delta);
871	        let local_ts_ns = epoch_ns.wrapping_add(local_delta);
872	        let block = attrs & ATTRS_BLOCK != 0;
873	        let rpi = attrs & ATTRS_RPI != 0;
874	        for _ in 0..count {
875	            let price_delta = read_zigzag(payload, &mut pos)?;
876	            let qty_delta = read_zigzag(payload, &mut pos)?;
877	            let price_ticks = st.prev_price_ticks.wrapping_add(price_delta);
878	            let qty_lots = st.prev_qty_lots.wrapping_add(qty_delta);
879	            st.prev_price_ticks = price_ticks;
880	            st.prev_qty_lots = qty_lots;
881	            out.push(Record {
882	                ev,
883	                exch_ts_ns,
884	                local_ts_ns,
885	                price_ticks,
886	                qty_lots,
887	                block,
888	                rpi,
889	            });
890	        }
891	    }
892	    Ok(out)
893	}
