648	impl FileReplayer {
649	    pub fn new() -> Self {
650	        Self {
651	            bids: Vec::new(),
652	            asks: Vec::new(),
653	            cur_snapshot: false,
654	            cur_ts_ns: 0,
655	            has_open: false,
