660	    fn flush(&mut self, updates: &mut Vec<Update>) {
661	        if !self.has_open {
662	            return;
663	        }
664	        let u = if self.cur_snapshot { 1 } else { self.next_u };
665	        if !self.cur_snapshot {
666	            self.next_u += 1;
667	        }
668	        // Файл `seq` не хранит: синтетика зеркалит `u` (проверки 2-3, не 1).
669	        // Глубина — потока основного файла (T45): реплей читает
670	        // `<root>/<SYMBOL>-<день>.binlog`, глубокий файл лежит отдельно и
671	        // этого признака в формате не несёт (v3 заморожен, В-49).
672	        updates.push(Update {
673	            is_snapshot: self.cur_snapshot,
674	            depth: ORDERBOOK_DEPTH,
675	            u,
676	            seq: u,
677	            cts_ms: self.cur_ts_ns / 1_000_000,
678	            bids: std::mem::take(&mut self.bids),
679	            asks: std::mem::take(&mut self.asks),
680	        });
681	        self.has_open = false;
682	    }
