684	    /// Принимает записи очередного кадра. Возвращает закрывшиеся обновления
685	    /// и точки сделок; незакрытая группа (одно сообщение, разрезанное границей
686	    /// кадра) остаётся внутри и допишется следующим кадром.
687	    pub fn push_frame(
688	        &mut self,
689	        records: &[Record],
690	        tick_e9: i64,
691	        step_e9: i64,
692	        updates: &mut Vec<Update>,
693	        trades: &mut Vec<TradePoint>,
694	    ) {
695	        for r in records {
696	            if is_trade_ev(r.ev) {
697	                self.flush(updates);
698	                trades.push(TradePoint {
699	                    tick: r.price_ticks,
700	                    block: r.block,
701	                    rpi: r.rpi,
702	                    exch_ms: r.exch_ts_ns / 1_000_000,
703	                    aggressor_is_buy: r.ev == LOCAL_BUY_TRADE_EVENT,
704	                });
705	                continue;
706	            }
707	            let Some(side) = depth_side(r.ev) else {
708	                continue;
709	            };
710	            let snap = is_snapshot_ev(r.ev);
711	            // Новое сообщение — новая группа: та же метка времени и тот же
712	            // вид кадра продолжают группу, всё остальное её закрывает.
713	            // Два разных сообщения с одной меткой (та же миллисекунда) честно
714	            // сливаются: порядок внутри миллисекунды всё равно неразличим, а
715	            // атомарность спасает от ложного пересечения.
716	            if self.has_open && (snap != self.cur_snapshot || r.exch_ts_ns != self.cur_ts_ns) {
717	                self.flush(updates);
718	            }
719	            if snap {
720	                self.next_u = 2;
721	            }
722	            if !self.has_open {
723	                self.cur_snapshot = snap;
724	                self.cur_ts_ns = r.exch_ts_ns;
725	                self.has_open = true;
726	            }
727	            let qty_e9 = r.qty_lots * step_e9;
728	            let px_e9 = r.price_ticks * tick_e9;
729	            match side {
730	                Side::Bid => self.bids.push((px_e9, qty_e9)),
731	                Side::Ask => self.asks.push((px_e9, qty_e9)),
732	            }
733	        }
734	    }
