284	            // Суток в кэше нет — символ пропускается, а не роняет весь прогон
285	            // (как у `lob fill-capacity --targets approaches`, F2): реплея
286	            // подходов у сетки нет, полосу `D` знает только прогон F1.
287	            let Ok(days) = cached_approaches(dir, symbol, parts_by_day.keys()) else {
288	                eprintln!(
289	                    "bounce-grid: {symbol} — кэш подходов не годится, символ пропущен (нужен прогон `lob touches --approach-bps D`)"
290	                );
291	                summary.symbols_without_touches += 1;
292	                continue;
293	            };
294	            summary.symbols_from_cache += 1;
295	            (days, SigmaSeries::from_mids(&[]))
296	        } else {
297	            match args
298	                .touches_from
299	                .as_deref()
