304	                    (days, SigmaSeries::from_mids(&[]))
305	                }
306	                Some(Err(why)) if args.touches_cache_only => {
307	                    eprintln!(
308	                        "bounce-grid: {symbol} — кэш касаний не годится ({why}), символ пропущен (--touches-cache-only)"
309	                    );
310	                    summary.symbols_without_touches += 1;
311	                    continue;
312	                }
313	                other => {
314	                    if let Some(Err(why)) = other {
315	                        eprintln!("bounce-grid: {symbol} — кэш касаний не годится ({why}), реплей");
316	                    }
317	                    let replay = replay_symbol_touches_and_second_mids(
318	                        &args.root,
