327	                    }
328	                    let days = replay
329	                        .days
330	                        .into_iter()
331	                        .map(|d| DayTouches {
332	                            rets: d
333	                                .touches
334	                                .iter()
335	                                .map(|t| {
336	                                    std::array::from_fn(|k| {
337	                                        super::touches::pre_touch_return_bps_csv(
338	                                            &d.mids,
339	                                            t.start_ms,
340	                                            super::touches::PRE_TOUCH_MS[k],
341	                                        )
342	                                    })
343	                                })
344	                                .collect(),
345	                            day: d.day,
346	                            touches: d.touches,
347	                            approaches: None,
348	                        })
349	                        .collect();
350	                    (days, SigmaSeries::from_mids(&all))
351	                }
352	            }
353	        };
354	        let touches_total: usize = days.iter().map(|d| d.touches.len()).sum();
355	        if touches_total == 0 {
356	            let what = if args.signal == SignalArg::Approach {
357	                "записей подхода"
358	            } else {
359	                "касаний"
