361	            eprintln!("bounce-grid: {symbol} — {what} нет, символ пропущен");
362	            summary.symbols_without_touches += 1;
363	            continue;
364	        }
365	        let sizing = OrderSizing::from_args(args, symbol)?;
366	        // Явный лот обязан быть целым числом шагов записи: ноги лестницы
367	        // (R3) считаются целыми шагами, и некратный лот молча менял бы размер
368	        // круга (0.25 при шаге 0.1 — `round(2.5)` = 3 шага, +20 %). Лот пула и
369	        // номинал (`--order-qty-from-pool`/`--order-usd`) кратны по построению.
370	        // Шаг записи — `qty_step` пула на момент записи (коллектор пишет его в
