372	        // размера (`drive_signal` проверяет это только в отладочной сборке).
373	        if let OrderSizing::Fixed(v) = sizing {
374	            anyhow::ensure!(
375	                v > 0 && step_e9 > 0 && v % step_e9 == 0,
376	                "{symbol}: --order-qty-e9 {v} не положителен или не кратен шагу лота записи                  {step_e9} (1e-9, qty_step пула при записи) — ноги лестницы округлили бы его молча"
377	            );
378	        }
