380	        for day in &days {
381	            // `--day`: гнать только выбранные сутки. Касания при этом считаются
382	            // по всей записи символа (возраст уровня и прогрев трекера не
383	            // зависят от границы суток), так что круги выбранного дня те же,
384	            // что и в прогоне без фильтра.
