386	                continue;
387	            }
388	            if day.touches.is_empty() {
389	                continue;
390	            }
391	            let Some(day_parts) = parts_by_day.get(&day.day) else {
392	                anyhow::bail!("{symbol}: сутки {} есть в реплее, но частей нет", day.day);
393	            };
394	            let day_started = Instant::now();
395	            let retries_before =
396	                crate::lob::backtest::HORIZON_RETRIES.load(std::sync::atomic::Ordering::Relaxed);
397	            // S4: события одних суток, не всей сессии.
398	            let mut events = day_events(day_parts)?;
399	            if events.is_empty() {
400	                eprintln!(
401	                    "bounce-grid: {symbol} {} — событий нет, сутки пропущены",
402	                    day.day
403	                );
404	                continue;
405	            }
406	            // Довесок (`--carry-root`): дописывает события D+1 в окне переноса
407	            // ДО построения окон сетапов — тот же приём, что уже склеивает
408	            // части одних суток (`day_events`: части хронологичны, каждая
409	            // несёт свой снапшот, поэтому конкатенация корректна без ручной
410	            // сшивки книги). Сигналы дня (`day.touches` ниже) от довеска не
411	            // зависят — он только дописывает хвост потока книги/сделок.
412	            let (carry_boundary_ns, carry_unverified) = match carry_window {
413	                Some(window) => extend_with_carry(
414	                    &mut events,
415	                    &day.day,
416	                    args.carry_root.as_deref(),
417	                    &carry_parts_by_day,
418	                    symbol,
419	                    window,
420	                )?,
421	                None => (None, false),
422	            };
423	            // S2: все формы над одним потоком событий, потоками; результат
424	            // каждой формы — сразу в дамп. Окна суток — один раз на все наборы.
