430	                        day.day.clone(),
431	                        read_regime_day(dir, &day.day, sets.iter().any(FilterSet::uses_btc_mid))?,
432	                    );
433	                }
434	                regime_days.get(&day.day)
435	            } else {
436	                None
437	            };
438	            let ctx = touch_contexts(&day.rets, &day.touches, regime);
439	            let order_qtys = sizing.touch_qtys(&day.touches, tick_e9, args.order_qty_mult);
440	            let mut rounds: u64 = 0;
441	            let day_label = day.day.clone();
442	            // G10: память кругов на символ-сутки, по форме — наборы идут по очереди и берут
443	            // посчитанные круги готовыми. Один набор повторов не даёт — памяти нет.
444	            let memos: Vec<Mutex<RoundMemo>> =
445	                if windows.is_some() && args.round_memo == "on" && sets.len() > 1 {
446	                    (0..forms.len())
447	                        .map(|_| Mutex::new(RoundMemo::default()))
448	                        .collect()
449	                } else {
450	                    Vec::new()
451	                };
452	            for (set, out) in sets.iter().zip(outs.iter_mut()) {
453	                let forms_done = {
454	                    let forms_ref = &forms;
455	                    let mut sink =
456	                        |r: FormDayResult, signals: &[BounceSignal]| -> anyhow::Result<()> {
457	                            let n = out.write_form(
458	                                symbol,
459	                                &day_label,
460	                                forms_ref[r.form],
461	                                signals,
462	                                &r.run,
463	                                r.skipped,
464	                                carry_boundary_ns,
465	                                carry_unverified,
466	                            )?;
467	                            rounds = rounds.saturating_add(n);
468	                            Ok(())
469	                        };
470	                    drive_day(
471	                        &events,
472	                        windows.as_ref(),
473	                        &day.touches,
474	                        day.approaches.as_deref(),
475	                        &forms,
476	                        DayParams {
477	                            memos: if memos.is_empty() {
478	                                None
479	                            } else {
480	                                Some(memos.as_slice())
481	                            },
482	                            tick,
483	                            lot,
484	                            rtt_ns: args.median_rtt_ns,
485	                            queue_model,
486	                            order_qtys: &order_qtys,
487	                            threads,
488	                            post_only: args.entry_post_only(),
489	                            frontrun_only: set.frontrun_only,
490	                            min_age_ms: set.min_age_secs.map(|s| s.saturating_mul(1_000)),
491	                            min_flow_pct: set.min_flow_pct,
492	                            side: set.side.map(Side::from),
493	                            eaten_max_pct: set.eaten_max_pct,
494	                            eaten_min_pct: set.eaten_min_pct,
495	                            usd_min: set.usd_min,
496	                            ctx: if set.uses_ctx() { Some(&ctx) } else { None },
497	                            ctx_ranges: set.ctx,
498	                            mode,
499	                            h3_usd: args.h3.h3_usd,
500	                            band_exit_bps,
501	                            sigma: &sigma_series,
502	                        },
503	                        &mut sink,
504	                    )?
505	                };
506	                anyhow::ensure!(
507	                    forms_done == forms.len(),
508	                    "{symbol} {} {}: форм посчитано {}, ожидалось {}",
509	                    day.day,
510	                    set.name,
511	                    forms_done,
512	                    forms.len()
513	                );
514	            }
515	            summary.rounds = summary.rounds.saturating_add(rounds);
516	            summary.symbol_days += 1;
517	            eprintln!(
518	                "bounce-grid: {symbol} {} touches={} events={} forms={} rounds={} {:.1}s",
519	                day.day,
520	                day.touches.len(),
521	                events.len(),
522	                forms.len(),
523	                rounds,
524	                day_started.elapsed().as_secs_f64()
525	            );
526	            // Р6: пересчёты кругов из-за короткого горизонта развёртки — строка только когда были
527	            // (прежний stderr не меняется); на итог не влияют, только на время.
528	            let retries = crate::lob::backtest::HORIZON_RETRIES
529	                .load(std::sync::atomic::Ordering::Relaxed)
530	                .saturating_sub(retries_before);
531	            if retries > 0 {
532	                eprintln!("bounce-grid:   горизонт развёртки: пересчётов кругов {retries}");
533	            }
534	            if !memos.is_empty() {
535	                let (hits, misses) = memos.iter().fold((0u64, 0u64), |(h, m), x| {
536	                    let (a, b) = x.lock().map(|g| g.stats()).unwrap_or((0, 0));
537	                    (h + a, m + b)
538	                });
539	                eprintln!(
540	                    "bounce-grid:   память кругов: из памяти {hits}, посчитано движком {misses}"
541	                );
542	            }
543	        }
544	        summary.symbols_done += 1;
545	        eprintln!(
546	            "bounce-grid: {symbol} готов — суток {}, касаний {}, {:.1}s",
547	            days.iter().filter(|d| !d.touches.is_empty()).count(),
548	            touches_total,
549	            started.elapsed().as_secs_f64()
550	        );
551	    }
552	    Ok(summary)
553	}
