18	// ---------------------------------------------------------------------------
19	// Перенос круга через полночь (`--carry-root`): круг, ещё открытый на конце
20	// суток D, дочитывает выход по данным D+1 вместо `RoundOutcome::EndOfData`
21	// (измерено на кандидате 23.09: 35 из 189 круга истории, 8 из 43 записи —
22	// см. doc `BounceGridArgs::carry_root`).
23	// ---------------------------------------------------------------------------
24	
25	/// Окно переноса, нс: сколько времени после полуночи D+1 ещё может
26	/// понадобиться, чтобы круг, открытый под конец суток D, дочитал свой выход.
27	/// Строится из чисел уже переданного прогона, не изобретённая константа:
28	/// наибольший потолок входа сетки (`--entry-ttl-secs`) плюс наибольший
29	/// `--deadline-secs` плюс небольшой запас на задержку исполнения (p95 RTT
30	/// тейкера — тот же параметр, что уже ограничивает выход рыночным ордером).
31	/// `EntryTtl::Touch` не добавляет времени: вход в этом режиме живёт не дольше
32	/// самого касания суток D (`touch.end_ms − touch.start_ms`), а касания —
33	/// собственные суток D, разбор их конца не выходит за пределы дня (F5,
34	/// `bounce_plan`). `EntryTtl::Wall` потолка не несёт (`entry_ttl_ns =
35	/// i64::MAX`, F5) — окно переноса с ним не построить, отказ, а не
36	/// изобретённое число.
37	pub(super) fn carry_window_ns(
38	    entry_ttls: &[EntryTtl],
39	    deadlines: &[u64],
40	    p95_taker_rtt_ns: i64,
41	) -> anyhow::Result<i64> {
42	    let mut max_entry_ttl_secs: i64 = 0;
43	    for ttl in entry_ttls {
44	        match ttl {
45	            EntryTtl::Touch => {}
46	            EntryTtl::Secs(secs) => max_entry_ttl_secs = max_entry_ttl_secs.max(*secs),
47	            EntryTtl::Wall => anyhow::bail!(
48	                "--carry-root: --entry-ttl-secs wall не ограничен по времени (F5, entry_ttl_ns = \
49	                 i64::MAX) — окно переноса не построить без числового потолка"
50	            ),
51	        }
52	    }
53	    let max_deadline_secs = deadlines.iter().copied().max().unwrap_or(0) as i64;
54	    Ok(max_entry_ttl_secs
55	        .saturating_add(max_deadline_secs)
56	        .saturating_mul(1_000_000_000)
57	        .saturating_add(p95_taker_rtt_ns))
58	}
59	
60	/// Следующие сутки UTC `YYYY-MM-DD` — довесок смотрит ровно на них, не дальше
61	/// (круг, переживший ещё и вторую полночь, остаётся `incomplete`, как и
62	/// прежде — сетка замера ограничивает окно, не гоняется за произвольной
63	/// глубиной).
64	fn next_day_utc(day: &str) -> anyhow::Result<String> {
65	    let d = chrono::NaiveDate::parse_from_str(day, "%Y-%m-%d")
66	        .map_err(|e| anyhow::anyhow!("сутки {day:?}: ожидается YYYY-MM-DD ({e})"))?;
67	    let next = d
68	        .succ_opt()
69	        .ok_or_else(|| anyhow::anyhow!("сутки {day}: следующих суток не построить"))?;
70	    Ok(next.format("%Y-%m-%d").to_string())
71	}
72	
73	/// Полночь UTC суток в наносекундах эпохи — граница переноса и колонка
74	/// `n_carried` (`forms.csv`): круг, чей `exit_ns ≥` эта граница, закрылся уже
75	/// на данных D+1.
76	pub(super) fn day_start_ns(day: &str) -> anyhow::Result<i64> {
77	    let d = chrono::NaiveDate::parse_from_str(day, "%Y-%m-%d")
78	        .map_err(|e| anyhow::anyhow!("сутки {day:?}: ожидается YYYY-MM-DD ({e})"))?;
79	    d.and_hms_opt(0, 0, 0)
80	        .and_then(|dt| dt.and_utc().timestamp_nanos_opt())
81	        .ok_or_else(|| anyhow::anyhow!("сутки {day}: полночь не строится в нс"))
82	}
83	
84	/// События суток-довеска D+1, ограниченные окном переноса (`until_ns`,
85	/// исключая) — не вся запись: тот же риск OOM, что решает двухпроходный
86	/// точный `Vec` `day_events` (её doc), только предел здесь не «конец файла»,
87	/// а окно. Части хронологичны (`session_parts_for`: день, потом часть) — как
88	/// только одна упёрлась в потолок, следующие начнутся ещё позже, читать их
89	/// незачем (`count_feed_events_until`/`feed_compact_into_until` уже говорят,
90	/// уткнулись ли).
91	#[cfg(test)]
92	pub(super) fn carry_events(parts: &[PathBuf], until_ns: i64) -> anyhow::Result<Vec<CompactEvent>> {
93	    let mut events = Vec::new();
94	    append_carry_events(parts, until_ns, &mut events)?;
95	    Ok(events)
96	}
97	
98	/// Довесок в окне — прямо в конец `events` (Р10, T-22, 26.09): сперва счёт событий
99	/// довеска, затем `reserve_exact` и декод на месте. Раньше довесок собирался
100	/// отдельным `Vec` и дописывался `extend`: буфер суток выделен ровно по размеру
101	/// (`day_events`), поэтому `extend` растил его амортизированно — ёмкость до
102	/// удвоения, плюс копия довеска рядом на время `extend` (LSKUSDT 14.09: 146,6 млн
103	/// событий суток не влезли в потолок 12 ГБ). События и их порядок те же — меняется
104	/// только выделение памяти. Возвращает число дописанных событий.
105	pub(super) fn append_carry_events(
106	    parts: &[PathBuf],
107	    until_ns: i64,
108	    events: &mut Vec<CompactEvent>,
109	) -> anyhow::Result<usize> {
110	    let mut total = 0usize;
111	    for path in parts {
112	        let mut feed = open_replay_feed(path)?;
113	        let (n, hit_bound) = count_feed_events_until(&mut feed, until_ns);
114	        total += n;
115	        if hit_bound {
116	            break;
117	        }
118	    }
119	    events.reserve_exact(total);
120	    let before = events.len();
121	    for path in parts {
122	        let mut feed = open_replay_feed(path)?;
123	        if feed_compact_into_until(&mut feed, until_ns, events) {
124	            break;
125	        }
126	    }
127	    Ok(events.len() - before)
128	}
