130	/// Довесок конца суток `day` данными D+1 (см. `carry_window_ns`): дописывает
131	/// `events` в окне времени и отвечает, что писать в `forms.csv` — границу
132	/// полуночи D+1 (`n_carried`, `None` — довесок не применился: нет
133	/// `--carry-root`, нет частей D+1 или сутки последние в записи, прежнее
134	/// `incomplete`) и флаг «части довеска без сверки» (K1: используются в любом
135	/// случае — довесок только дочитывает уже открытые круги дня D, не заводит
136	/// новых сигналов, — но отсутствие маркера считается).
137	#[allow(clippy::too_many_arguments)]
138	pub(super) fn extend_with_carry(
139	    events: &mut Vec<CompactEvent>,
140	    day: &str,
141	    carry_root: Option<&Path>,
142	    carry_parts_by_day: &BTreeMap<String, Vec<PathBuf>>,
143	    symbol: &str,
144	    window_ns: i64,
145	) -> anyhow::Result<(Option<i64>, bool)> {
146	    let Some(carry_root) = carry_root else {
147	        return Ok((None, false));
148	    };
149	    let next_day = next_day_utc(day)?;
150	    let Some(next_parts) = carry_parts_by_day.get(&next_day) else {
151	        return Ok((None, false));
152	    };
153	    let boundary = day_start_ns(&next_day)?;
154	    let until = boundary.saturating_add(window_ns);
155	    let n_carry = append_carry_events(next_parts, until, events)?;
156	    eprintln!(
